Translate("deDE", "stonetalon-mountains", {
	title = "Steinkrallengebirge",
	aliases = { "Steinkrallen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Steinkrallengebirge ist ein Wall aus grauen Gipfeln und tiefgrünen Tälern im Westen von {link:kalimdor}Kalimdor{/link}, zwischen den Wäldern des {link:ashenvale}Eschentals{/link} im Norden und den Ebenen von {link:mulgore}Mulgore{/link} und dem {link:the-barrens}Brachland{/link} im Süden und Osten. Auf seiner Krone steht der {link:stonetalon-peak}Steinkrallengipfel{/link}, eine Höhe, die den Druiden der {link:night-elves}Nachtelfen{/link} seit Langem heilig ist. Unter ihm fällt das Land in Seen, Schluchten und Wälder aus gewaltigen Bäumen ab. Viele dieser Bäume sind nun verschwunden. Die {link:venture-company}Venture Co.{/link} ist mit Sägen und Feuer ins Steinkrallengebirge gekommen, und wo ihre Maschinen vorübergezogen sind, schreien die Geister des Landes vor Schmerz.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wie die Berge sich erhoben oder wer ihnen zuerst ihren Namen gab. Bekannt ist, dass das Steinkrallengebirge ein heiliger Ort war, lange bevor die jüngeren Völker nach {link:kalimdor}Kalimdor{/link} kamen. Die Druiden der Kaldorei errichteten den {link:the-talon-den}Krallenbau{/link} hoch oben auf dem Gipfel und bewahrten darin ihre Schätze auf. Zwischen den Steinen des Gipfels liegen die Ruinen eines noch älteren Werks: ein Tempel aus dem Zeitalter von {link:queen-azshara}Königin Azshara{/link}, an dessen Erbauer sich nur wenige erinnern und um die noch weniger trauern. Der Wald, der die Täler darunter bedeckte, stand in der Obhut der Söhne und Töchter des Halbgottes {link:cenarius}Cenarius{/link}, und er wuchs ungestört länger, als irgendein Sterblicher ermessen kann.

Im {link:third-war}Dritten Krieg{/link} trat der Gipfel in die Geschichte der jüngeren Völker ein. In das Steinkrallengebirge sandte {link:cairne-bloodhoof}Cairne Bloodhoof{/link} den jungen Kriegshäuptling {link:thrall}Thrall{/link}, auf der Suche nach einem Orakel, das im Berg wohnte. Dort begegneten die Anführer der {link:horde}Horde{/link} und die {link:humans}Menschen{/link} aus {link:lordaeron}Lordaeron{/link} dem Propheten, der sie nach Westen gerufen hatte, und erfuhren, dass er {link:medivh}Medivh{/link} war.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Das Steinkrallengebirge ist ein Land im Krieg mit sich selbst. Goblins der {link:venture-company}Venture Co.{/link} sind über die Wälder der Scherwindklippe hergefallen, und ihre Schredder fällen in einer Stunde, was in tausend Jahren gewachsen ist. Als sie in das verbrannte Tal vordrangen, wehrte sich etwas in dem Tal, und die Goblins setzten es auf ihrem Rückzug in Brand. Nun wandeln Feuerelementare durch die Asche. Die {link:harpies}Harpyien{/link} der Blutfurien haben ihre Nester in den geschwärzten Hügeln gebaut, und von dort breiten sie sich über den ganzen Kontinent aus.

Weder die {link:alliance}Allianz{/link} noch die {link:horde}Horde{/link} wird die Berge aufgeben. Die {link:night-elves}Nachtelfen{/link} halten den {link:stonetalon-peak}Steinkrallengipfel{/link}, und eine Schildwache und ein gnomischer Magier arbeiten am Rand der Scherwindklippe gemeinsam gegen die Goblins. Die Horde hält {link:sun-rock-retreat}Sonnenfels{/link} im Herzen des Gebirges, wo {link:tauren}Tauren{/link} und {link:orcs}Orcs{/link} das Land zu heilen suchen. In {link:malaka-jin}Malaka'jin{/link}, im fernen Süden, jagen und brauen {link:darkspear-trolls}Trolle der Darkspear{/link}. Im Südosten haben die {link:grimtotem-clan}Grimmtotem{/link} ein eigenes Kriegslager errichtet. In einem sind sie sich alle einig: Die Venture Co. muss verschwinden. In wenig anderem sind sie sich einig.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Kaldorei des Gipfels.{/b} Druiden und {link:sentinels}Schildwachen{/link} hüten den {link:stonetalon-peak}Steinkrallengipfel{/link} und den {link:the-talon-den}Krallenbau{/link}. Sie sind wenige, und sie sind wachsam.
• {b}Die {link:horde}Horde{/link} von {link:sun-rock-retreat}Sonnenfels{/link}.{/b} {link:tauren}Tauren{/link}, {link:orcs}Orcs{/link} und jene, die gekommen sind, um an ihrer Seite zu kämpfen, halten Sonnenfels, das einzige sichere Dach zwischen dem {link:the-barrens}Brachland{/link} und {link:desolace}Desolace{/link}.
• {b}Die {link:venture-company}Venture Co.{/link}{/b} Holzfäller, Bergleute und Ingenieure der Goblins bearbeiten die Scherwindklippe mit großen Maschinen, bewacht von angeheuerten Kräften.
• {b}Die {link:harpies}Harpyien{/link} der Blutfurien.{/b} Sie nisten im verbrannten Tal, und ihre Königin beherrscht sie von dessen westlichen Hügeln aus.
• {b}Die Grimmtotem.{/b} Eine Kriegsschar dieses Taurenclans hält den {link:grimtotem-post}Posten der Grimmtotem{/link} im Südosten und überfällt die Dörfer des eigenen Volkes.
• {b}Kobolde, Spinnen und Wyvern.{/b} {link:kobolds}Kobolde{/link} graben in den Tiefen der {link:boulderslide-ravine}Steinschlagklamm{/link}. Große Spinnen jagen nachts auf dem {link:webwinder-path}Weberpass{/link}. Pridewing-Wyvern nisten auf den hohen Klippen.
• {b}Die {link:trolls}Trolle{/link} von {link:malaka-jin}Malaka'jin{/link}.{/b} Ein Dorf der {link:darkspear-trolls}Darkspear{/link} liegt am südlichen Fuß der Berge, wo die Straße aus dem Brachland heraufsteigt.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Zeitalter der Druiden.{/b} Seit ungezählten Zeitaltern gehörte das Steinkrallengebirge dem Wald und jenen, die ihn behüteten. Die Druiden des Gipfels und die Kinder des {link:cenarius}Cenarius{/link} hielten die Täler grün.
• {b}Das Orakel.{/b} Während des Dritten Krieges kam {link:thrall}Thrall{/link} auf der Suche nach dem Orakel ins Steinkrallengebirge, und dort drängte {link:jammal-an-the-prophet}der Prophet{/link} {link:medivh}Medivh{/link} {link:orcs}Orc{/link} und Mensch, sich gegen das Kommen der {link:burning-legion}Brennenden Legion{/link} zu vereinen.
• {b}Die Ankunft der {link:horde}Horde{/link}.{/b} Nach der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} schufen sich die Horde und die {link:tauren}Tauren{/link} ihre Heimat in {link:kalimdor}Kalimdor{/link}. {link:sun-rock-retreat}Sonnenfels{/link} wurde in den Bergen errichtet, und die {link:darkspear-trolls}Darkspear{/link} ließen sich in {link:malaka-jin}Malaka'jin{/link} nieder. Keine Chronik verzeichnet das Jahr des einen oder des anderen.
• {b}Der Einfall der Goblins.{/b} Die {link:venture-company}Venture Co.{/link} kam in die Berge, um Holz zu schlagen und Erz zu graben. Sie entblößte die Scherwindklippe, brannte das verbrannte Tal nieder und vergiftete die Geister des Landes.
• {b}Die Gegenwart.{/b} Druiden, Schamanen, {link:sentinels}Schildwachen{/link} und {link:gnomes}Gnome{/link} kämpfen nun darum, zu heilen, was die Goblins zerbrochen haben. Die Goblins wehren sich, und die {link:harpies}Harpyien{/link}, {link:grimtotem-clan}die Grimmtotem{/link} und die Feuergeister kämpfen gegen alle.]=],
		},
		{
			title = "Überlieferungen der Berge",
			text = [=[• Die Schamanen sagen, die Geister des Steinkrallengebirges seien vor Schmerz und Zorn beinahe blind. Wer auf solche Dinge lauscht, hat das Land selbst aufschreien hören.
• Die {link:harpies}Harpyien{/link} der Blutfurien sollen der Ursprung der Harpyienplage in ganz {link:kalimdor}Kalimdor{/link} sein. Die Witchwing des Brachlands kamen aus diesen Bergen.
• Hoch oben auf dem Gipfel wohnte einst einer der ältesten Söhne des {link:cenarius}Cenarius{/link}. Sein Name war {link:keeper-ordanus}Ordanus{/link}, und er wurde im Geheimen fortgebracht, als ein Feind kam, um ihn zu jagen.
• Die Gaea-Samen des Mirkfallonsees sollen der Verderbnis widerstehen. Die {link:tauren}Tauren{/link} pflanzen sie in die Asche des verbrannten Tals, in der Hoffnung, dass dort eines Tages ein neuer Wald wachsen wird.
• Unter der {link:boulderslide-ravine}Steinschlagklamm{/link} fanden {link:kobolds}Kobolde{/link} einen Kristall namens Resonit. Wo er lag, schlief etwas, das älter war als die Kobolde.]=],
		},
	},
})

Translate("deDE", "stonetalon-peak", {
	title = "Steinkrallengipfel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Steinkrallengipfel ist die Krone der Berge, ein hoher, grüner Gipfel im äußersten Nordwesten des Gebirges. Die {link:night-elves}Nachtelfen{/link} hüten ihn seit Zeitaltern, und in diesen Tagen wacht {link:keeper-albagorm}Bewahrer Albagorm{/link} mit einer Handvoll Druiden, {link:sentinels}Schildwachen{/link} und freundlich gesinnter Treants über ihn. Ein kleines Gasthaus dient jenen, die ihn erreichen, und Hippogryphen tragen Nachrichten ins {link:ashenvale}Eschental{/link} und weiter. Der Gipfel ist den Kaldorei heilig, doch er birgt ältere und seltsamere Dinge: die Ruinen eines Tempels aus dem Zeitalter Azsharas und die Gewölbe des Krallenbaus. Von hier aus wurde {link:keeper-ordanus}Ordanus{/link}, ein Sohn des {link:cenarius}Cenarius{/link}, in Sicherheit gebracht.]=],
		},
	},
})

Translate("deDE", "the-talon-den", {
	title = "Der Krallenbau",
	aliases = { "Krallenbau" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Krallenbau liegt in den hohen westlichen Senken des Steinkrallengipfels. Die Druiden erbauten ihn, um Gegenstände der Macht aufzubewahren, und sie ersannen einen sorgfältigen Plan, damit diese Schätze nicht in die falschen Hände fielen: ein Schlüssel, in einer Laterne am Eingang versteckt, Verstecke, die über den Bau verstreut sind, und ein Hort, der sich nur drei Schlüsseln zusammen öffnet. Druiden des Ordens des {link:cenarius}Cenarius{/link} bewachen ihn noch immer, zusammen mit einem Torwächter, einem Schlüsselmeister und den Dryaden und Hütern von {link:mirkfallon-lake}Mirkfallon{/link}. Ein seltener Feendrache, Nal'taszar, wurde zwischen den Bäumen darüber gesehen.]=],
		},
	},
})

Translate("deDE", "sun-rock-retreat", {
	title = "Sonnenfels",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sonnenfels ist die Festung der {link:horde}Horde{/link} im Herzen des Steinkrallengebirges. Er steht auf einer Felserhebung inmitten des Gebirges, bewacht von Grunzern der {link:orcs}Orcs{/link} und erreichbar über gewundene Straßen aus dem {link:the-barrens}Brachland{/link} und aus {link:desolace}Desolace{/link}. Seine Anführer sind zumeist {link:tauren}Tauren{/link}. {link:maggran-earthbinder}Maggran Earthbinder{/link} befehligt seine Verteidigung. {link:tammra-windfield}Tammra Windfield{/link} und {link:mor-rogal}Mor'rogal{/link} pflegen das verwundete Land, während ein Wassergeist namens {link:tsunaman}Tsunaman{/link} seinen eigenen Krieg gegen das Feuer führt. Ein Gasthaus, ein Windreiterposten und eine Handvoll Händler machen ihn zu einem Ort, an dem Reisende rasten können. Hier sammelt die Horde auch ihre Kräfte gegen die {link:harpies}Harpyien{/link}, die Goblins und {link:grimtotem-clan}die Grimmtotem{/link}.]=],
		},
	},
})

Translate("deDE", "windshear-crag", {
	title = "Die Scherwindklippe",
	aliases = { "Scherwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Scherwindklippe ist das große östliche Tal des Steinkrallengebirges und der Ort, an dem die {link:venture-company}Venture Co.{/link} ihr Schlimmstes getan hat. Wo einst alter Wald stand, bedecken nun Baumstümpfe die Hänge. Sägewerke und Wasserräder säumen die Bäche, und die Schredder XT:4 und XT:9 stapfen durch die Bäume. Tief in den Hügeln bearbeiten Goblins und angeheuerte Bergleute die Scherwindmine nach einem seltsamen goldgrünen Erz. Irgendwo im Tal unterhält die Gesellschaft einen kleinen Flughafen für ihre Flugmaschinen. Am westlichen Rand der Klippe halten eine Schildwache der {link:night-elves}Nachtelfen{/link} und ein gnomischer Magier gemeinsam Wache, und nicht weit von ihnen schmiedet ein Gobliningenieur, einst im Dienst der Gesellschaft, Pläne gegen seine früheren Herren.]=],
		},
	},
})

Translate("deDE", "cragpool-lake", {
	title = "Felskesselsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Felskesselsee liegt im Norden der Scherwindklippe. Seine Ufer sind zum Herzen der Werke der {link:venture-company}Venture Co.{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link} geworden. Südlich des Sees steht ein Sägewerk, in dem die Gesellschaft ihre technischen Pläne aufbewahrt. Hoch über dem Wasser, nahe einem großen Wasserrad, wacht der {link:gnomes}Gnom{/link} {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link} über die ganze Anlage. Reisende aus dem {link:ashenvale}Eschental{/link}, die durch den {link:the-talondeep-path}Steinkrallenpfad{/link} herabkommen, müssen auf ihrem Weg nach Südwesten zum Gipfel am See vorbei.]=],
		},
	},
})

Translate("deDE", "mirkfallon-lake", {
	title = "Mirkfallonsee",
	aliases = { "Mirkfallon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Mirkfallonsee ist ein großer, runder See in der Mitte des Gebirgspasses, nördlich von {link:sun-rock-retreat}Sonnenfels{/link}. Zwei bemerkenswerte Pflanzen wachsen an seinen Wassern. Die erste ist der Gaea-Samen, der nahe dem Ufer zu finden ist und den die {link:tauren}Tauren{/link} schätzen, weil er der Verderbnis widersteht und verwüstetem Boden das Leben zurückbringen kann. Die zweite ist das Mirkkraut, dessen Schoten getrocknet ein leuchtendes Rot annehmen und ein feines Pigment für Farbe ergeben. Der See ist schön und wild, und wer seine Gaben sammelt, muss sich vor den Tieren in Acht nehmen, die dort trinken.]=],
		},
	},
})

Translate("deDE", "the-charred-vale", {
	title = "Das verbrannte Tal",
	aliases = { "Verbranntes Tal", "Tal der Blutfurien" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das verbrannte Tal liegt im Westen der Berge, südlich des Steinkrallengipfels. Einst war es ein üppiger Wald. Als die {link:venture-company}Venture Co.{/link} in {link:stranglethorn-vale}das Tal{/link} vordrang, trieben seine Hüter sie zurück, und die Goblins steckten den Wald auf ihrer Flucht in Brand. Ihre Waffen verdarben die Treants, die gegen sie kämpften, und das Feuer entfesselte brennende Geister aus Flamme, Stein und Zorn. Nun ist das Tal Asche und Rauch. Die {link:harpies}Harpyien{/link} der Blutfurien nisten in seinen Hügeln, im Tal der Blutfurien, und ihre Königin hält seine westlichen Kämme. Kaldorei wie {link:tauren}Tauren{/link} träumen davon, es wieder grün zu machen.]=],
		},
	},
})

Translate("deDE", "greatwood-vale", {
	title = "Hochwipfeltal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Hochwipfeltal liegt im Südosten des Steinkrallengebirges, wo die Straße von {link:the-crossroads}Crossroads{/link} aus dem {link:the-barrens}Brachland{/link} in die Berge hinaufsteigt. Sein Name erinnert an die riesigen Bäume, die es füllen. Die Schamanin der {link:horde}Horde{/link} {link:seereth-stonebreak}Seereth Stonebreak{/link} schlug ihr Lager nahe dem Tal auf, als sie ausgesandt wurde, um auf die Schreie des Landes zu antworten, und von seinem Rand aus führt der Pfad nach Nordwesten in die Scherwindklippe und mitten in die Fänge der {link:venture-company}Venture Co.{/link}]=],
		},
	},
})

Translate("deDE", "webwinder-path", {
	title = "Weberpass",
	aliases = { "Sishircanyon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Weberpass ist die lange Straße durch die südlichen Täler des Steinkrallengebirges, die {link:sun-rock-retreat}Sonnenfels{/link} mit {link:malaka-jin}Malaka'jin{/link} und dem {link:the-barrens}Brachland{/link} verbindet. Er hat seinen Namen von den Spinnen, die ihn heimsuchen. Am dichtesten sind sie im Sishircanyon, westlich der Straße, wo die große Spinne {link:besseleth}Besseleth{/link} und ihre Brut einen mit Netzen verhangenen Unterschlupf angelegt haben. Nachts kommen sie heraus, um zu jagen, und Reisende, die den Pfad nach Einbruch der Dunkelheit begehen, erreichen nicht immer sein Ende. Selbst die {link:trolls}Trolle{/link} von Malaka'jin, die wenig fürchten, bleiben nahe bei ihren Feuern, wenn die Sonne untergegangen ist.]=],
		},
	},
})

Translate("deDE", "malaka-jin", {
	title = "Malaka'jin",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Malaka'jin ist ein Trolldorf am südlichen Fuß des Steinkrallengebirges, wo die Straße aus dem {link:the-barrens}Brachland{/link} ansteigt. Seine Bewohner sind {link:darkspear-trolls}Darkspear{/link}, und sie sind hier durch die reiche Jagd in den Hügeln zu Wohlstand gekommen. Das Dorf ist bekannt für seine Heiltränke und für seine Hexendoktoren, allen voran {link:witch-doctor-jin-zil}Jin'Zil{/link}, der drei gefangene {link:night-elves}Nachtelfen{/link} in Käfigen neben seiner Hütte hält. Spinnen überfallen das Lager bei Nacht, und seine Jäger wollen sie loswerden. Der {link:grimtotem-post}Posten der Grimmtotem{/link} liegt nicht weit im Norden.]=],
		},
	},
})

Translate("deDE", "boulderslide-ravine", {
	title = "Steinschlagklamm",
	aliases = { "Steinschlaghöhle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Steinschlagklamm ist eine tiefe Schlucht im Süden des Steinkrallengebirges, südöstlich von {link:sun-rock-retreat}Sonnenfels{/link}. In ihrer Wand öffnet sich eine Höhle, und in dieser Höhle graben {link:kobolds}Kobolde{/link} unter Gogger Stonepounder fieberhaft nach einem seltenen Kristall namens Resonit. Am Grund ihrer Tunnel fanden sie mehr als Kristall. In einem Behältnis aus Resonit lag {link:goggeroc}Goggeroc{/link}, ein Irdener, der seit vergessenen Zeitaltern schlief. Die Schamanen von Sonnenfels zählen dies zu den schwersten Gefahren in den Bergen.]=],
		},
	},
})

Translate("deDE", "grimtotem-post", {
	title = "Posten der Grimmtotem",
	aliases = { "Camp Aparaje" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Posten der Grimmtotem ist ein Kriegslager des {link:grimtotem-clan}Clans der Grimmtotem{/link} im Südosten des Steinkrallengebirges, oberhalb der Straße ins {link:the-barrens}Brachland{/link}. Von hier aus fielen {link:grundig-darkcloud}Grundig Darkcloud{/link} und seine Schläger über ein Taurendorf her und töteten fast alle seine Bewohner. Das Mädchen {link:kaya-flathoof}Kaya Flathoof{/link} wurde als Gefangene ins Lager gebracht. Camp Aparaje liegt in der Nähe. Dorthin bat Kaya gebracht zu werden, als sie befreit wurde, denn von dort kannte sie den Weg nach Hause.]=],
		},
	},
})

Translate("deDE", "the-talondeep-path", {
	title = "Der Steinkrallenpfad",
	aliases = { "Steinkrallenpfad" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Steinkrallenpfad ist ein Tunnel durch die Berge, der den Nordosten des Steinkrallengebirges mit dem südlichen {link:ashenvale}Eschental{/link} verbindet, nicht weit vom {link:mystral-lake}Mystralsee{/link}. Er ist die Straße der Kaldorei, die nach Süden zum Gipfel kommen, und jedes Reisenden, der das {link:the-barrens}Brachland{/link} lieber nicht durchqueren will. An seiner Mündung im {link:stonetalon-mountains}Steinkrallengebirge{/link}, oberhalb der Scherwindklippe, hat der Schamane der {link:horde}Horde{/link} {link:braug-dimspirit}Braug Dimspirit{/link} sein Lager und prüft die Weisheit derer, die zu ihm kommen.]=],
		},
	},
})

Translate("deDE", "keeper-albagorm", {
	title = "Bewahrer Albagorm",
	subtitle = "Bewahrer des Steinkrallengipfels",
	found = "Steinkrallengipfel",
	hint = [=[Steigt zur Krone der Berge hinauf und sprecht mit dem Bewahrer, der über sie wacht.]=],
	allegiance = "Darnassus · Druiden des Gipfels",
	aliases = { "Albagorm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bewahrer Albagorm ist der kaldoreische Hüter des Steinkrallengipfels. Er nennt sich einen Beschützer der Waldgeister, und vom Gipfel aus hat er gesehen, wie die Wälder unter ihm Feuer und Säge zum Opfer fielen. Er hat nicht geweint. Er hat geplant. Seine Antwort auf die Verwüstung des verbrannten Tals ist nicht Rache allein, sondern neues Wachstum, und er will {link:stranglethorn-vale}das Tal{/link} wieder grün sehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Albagorm ist die Stimme des alten Glaubens der Kaldorei im {link:stonetalon-mountains}Steinkrallengebirge{/link}. Er sieht das Land als ein einziges lebendes Wesen, und die Goblins und {link:harpies}Harpyien{/link} als Wunden darauf. Er weiß auch, dass die Druiden des Gipfels es nicht allein heilen können, und er sucht Hilfe bei Druiden bis hin nach {link:feralas}Feralas{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wacht über den {link:stonetalon-peak}Steinkrallengipfel{/link} und die Druiden, die dort leben.
• Er sendet Reisende gegen die {link:harpies}Harpyien{/link} der Blutfurien, die den Druiden den Weg ins verbrannte Tal versperren.
• Er sucht die Hilfe des Druiden {link:falfindel-waywarder}Falfindel Waywarder{/link} aus {link:feralas}Feralas{/link}, der große Geister des Waldes in das verwüstete Tal rufen kann.
• Er empfängt die Reisenden, die die Waldgeister ihm aus dem {link:ashenvale}Eschental{/link} senden.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik erzählt, wie lange Albagorm den Gipfel schon hütet oder was er tat, bevor die Goblins kamen.]=],
		},
	},
	chapters = {
		{
			title = "Die Schande des Tals",
			hint = "Folgt dem Ruf des Bewahrers und säubert das verbrannte Tal.",
			text = [=[Albagorm nennt die Ursache der Verwüstung des verbrannten Tals unverblümt beim Namen: Gier. Die Maschinen der Goblins setzten {link:stranglethorn-vale}das Tal{/link} in Brand, und nun hausen die {link:harpies}Harpyien{/link} der Blutfurien in seiner Asche und vertreiben jeden Druiden, der kommt, um neu zu pflanzen. Bevor das Tal geheilt werden kann, müssen die Harpyien vertrieben werden. Er bittet nicht um Gnade für sie.]=],
		},
		{
			title = "Ein Ruf nach Feralas",
			hint = "Tragt die Bitte des Bewahrers weit in den Süden.",
			text = [=[Die {link:harpies}Harpyien{/link} sind zerschlagen, doch sie werden zurückkehren. Albagorm weiß, dass Samen allein ihnen nicht zuvorkommen können. Er sendet Nachricht quer durch ganz {link:kalimdor}Kalimdor{/link} an den Druiden {link:falfindel-waywarder}Falfindel Waywarder{/link} am Rand der Wälder von {link:feralas}Feralas{/link}. Der Bewahrer glaubt, dass nur die großen Geister des Waldes {link:stranglethorn-vale}das Tal{/link} rechtzeitig zurückgewinnen können.]=],
		},
	},
	mentions = {
		{
			text = [=[Reise zum {link:stonetalon-peak}Steinkrallengipfel{/link}, gesandt vom Druiden {link:faldreas-goeth-shael}Faldreas{/link}]=],
		},
		{ text = "Die Rückeroberung des verbrannten Tals" },
		{
			text = [=[Die Rückeroberung des verbrannten Tals, der Ruf an {link:falfindel-waywarder}Falfindel{/link}]=],
		},
	},
	bonds = {
		{ id = "kaela-shadowspear", name = "Kaela Shadowspear", note = "kämpft in der Scherwindklippe gegen denselben Feind" },
		{ id = "bloodfury-ripper", name = "Bloodfury Ripper", note = "Königin der Harpyien, die er vertreiben will" },
		{ id = "braelyn-firehand", name = "Braelyn Firehand", note = "jagt die Druiden seines Gipfels" },
	},
})

Translate("deDE", "kaela-shadowspear", {
	title = "Kaela Shadowspear",
	subtitle = "Schildwache des Steinkrallengebirges",
	found = "Der Aussichtspunkt am westlichen Rand der Scherwindklippe",
	hint = [=[Sucht die Schildwache, die über das Tal wacht, durch das man die Scherwindklippe betritt.]=],
	allegiance = "Schildwachen · Darnassus",
	aliases = { "Kaela" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kaela Shadowspear ist eine Schildwache aus dem {link:ashenvale}Eschental{/link}, die ins {link:stonetalon-mountains}Steinkrallengebirge{/link} gesandt wurde, um herauszufinden, was mit dem Land geschah. Sie fand die Wälder der Scherwindklippe abgeholzt und das verbrannte Tal in Flammen. Seitdem ist sie geblieben und bekämpft die Goblins von einem Aussichtspunkt oberhalb der Klippe. An ihrer Seite arbeitet der gnomische Magier {link:gaxim-rustfizzle}Gaxim Rustfizzle{/link}, eine Partnerschaft, die ihr eigenes Volk kaum glauben mag.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kaela ist der Beweis dafür, wie ernst die Lage geworden ist. Eine Nachtelfe und ein {link:gnomes}Gnom{/link}, eine Schildwache, die dem Arkanen misstraut, und ein Magier, der daran Freude hat, haben sich gegen einen gemeinsamen Feind zusammengetan. Kaela bittet andere, {link:gaxim-rustfizzle}Gaxim{/link} nicht vorschnell zu verurteilen. Dass sie das überhaupt sagen kann, ist ein Zeichen der Zeit.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie wurde auf Befehl der Schildwache Wolfrunner ins {link:stonetalon-mountains}Steinkrallengebirge{/link} gesandt, und ihre Freundin {link:sentinel-thenysil}Tara Thenysil{/link} in {link:astranaar}Astranaar{/link} wartet schon lange auf Nachricht von ihr.
• Sie bekämpft die Zerstörung der Wälder durch die {link:venture-company}Venture Co.{/link}
• Sie jagt die brennenden Geister, die im verbrannten Tal entfesselt wurden.
• Sie nimmt den verwundeten Treants des Tals Splitter ab, damit {link:gaxim-rustfizzle}Gaxim{/link} erfahren kann, wie sie verdorben wurden.]=],
		},
	},
	chapters = {
		{
			title = "Das weinende Tal",
			hint = [=[Helft der Schildwache gegen die brennenden Geister des verbrannten Tals.]=],
			text = [=[Als Kaela das verbrannte Tal zum ersten Mal sah, hätte sie beinahe geweint. Die Goblins hatten nicht nur die Bäume verbrannt. In ihrer Torheit hatten sie Elementare aus Flamme, Stein und Zorn entfesselt, und solange diese Geister durch {link:stranglethorn-vale}das Tal{/link} wandeln, sagt sie, hat das Land keine Aussicht, das Lächeln Elunes zu sehen.]=],
		},
		{
			title = "Nachricht nach Astranaar",
			hint = "Bringt die Neuigkeiten der Schildwache heim ins Eschental.",
			text = [=[Als den Goblins ein Schlag versetzt worden ist, sendet Kaela endlich Nachricht nach Norden: Sie und {link:gaxim-rustfizzle}Gaxim{/link} leben, und sie sind auf gutem Weg, die {link:venture-company}Venture Co.{/link} aufzuhalten. In {link:astranaar}Astranaar{/link} hört {link:sentinel-thenysil}Tara Thenysil{/link} die Nachricht und freut sich, und nicht nur um Kaelas willen. Sie merkt, dass sie sich auch für den {link:gnomes}Gnom{/link} freut.]=],
		},
	},
	mentions = {
		{
			text = [=[Wache im {link:stonetalon-mountains}Steinkrallengebirge{/link}, gesandt von {link:sentinel-thenysil}Schildwache Thenysil{/link}]=],
		},
		{
			text = [=[Wache im {link:stonetalon-mountains}Steinkrallengebirge{/link}]=],
		},
		{ text = "Erzürnte Geister" },
		{ text = "Verwundete Uralte" },
		{
			text = [=[Kaelas Bericht, von {link:gaxim-rustfizzle}Gaxim{/link} überbracht]=],
		},
		{
			text = [=[Bericht für {link:sentinel-thenysil}Schildwache Thenysil{/link}]=],
		},
	},
	bonds = {
		{ id = "gaxim-rustfizzle", name = "Gaxim Rustfizzle", note = "ihr ungleicher Partner" },
		{ id = "keeper-albagorm", name = "Bewahrer Albagorm", note = "hütet den Gipfel über ihr" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "erfährt von ihrer Mission" },
	},
})

Translate("deDE", "gaxim-rustfizzle", {
	title = "Gaxim Rustfizzle",
	subtitle = "Gnom der Enlightened Assembly",
	found = [=[Neben Kaela Shadowspear, am westlichen Rand der Scherwindklippe]=],
	hint = [=[Sucht den Gnom, der neben der Schildwache oberhalb der Scherwindklippe arbeitet.]=],
	allegiance = [=[Gnomeregangnome · Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences]=],
	aliases = { "Gaxim" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gaxim Rustfizzle ist ein gnomischer Magier und Tüftler und ein stolzes Mitglied einer gelehrten Gesellschaft mit einem sehr langen Namen: der Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. Er kam mit der Schildwache {link:kaela-shadowspear}Kaela Shadowspear{/link} ins {link:stonetalon-mountains}Steinkrallengebirge{/link}. Er glaubt mit der ganzen Kraft seiner kleinen Gestalt, dass eine Mischung aus Magie, Mixturen und Mechanismen die Wälder der {link:night-elves}Nachtelfen{/link} retten kann. Er gedenkt es mit Sprengstoff zu beweisen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gaxim steht für eine Idee, der sich die Kaldorei lange widersetzt haben: dass Magie und Handwerk, gut eingesetzt, dem Wald dienen können, statt ihm zu schaden. Er sagt offen, dass die {link:night-elves}Nachtelfen{/link} Magie brauchen und dass die Welt sie braucht. Sein Krieg gegen die {link:venture-company}Venture Co.{/link} ist sein Argument.]=],
		},
		{
			title = "Taten",
			text = [=[• Er treibt die Goblins mit gut platzierten Sprengungen entlang der Ränder der Berge zurück.
• Er ersinnt ferngezündete Sprengladungen aus einer seltenen Verbindung, NG-5, und einem Botschaftszauber.
• Er plant zwei Überfälle auf die {link:venture-company}Venture Co.{/link}, einen auf ihre technischen Pläne und einen auf ihre Briefe.
• Er untersucht die Splitter der verdorbenen Treants des verbrannten Tals.]=],
		},
	},
	chapters = {
		{
			title = "Eine Fernzündung",
			hint = "Beschafft, was der Gnom für seine Sprengvorrichtung braucht.",
			text = [=[Gaxims Plan brauchte zwei Dinge, die er nicht selbst herstellen konnte. Das erste war Nitromirglyceronium, oder NG-5, das nur sein alter Kollege Lomac Gearstrip aus {link:tinker-town}Tinker Town{/link} brauen konnte. Das zweite war ein Zauber, der eine Ladung aus der Ferne zünden ließ, und dafür schrieb er an Collin Mauren, einen Magier aus {link:stormwind-city}Stormwind{/link}. Als beides in seine Hände gelangte, erklärte Gaxim seine Vorrichtung für vollkommen. Die Wagen mit Dynamit standen bereit.]=],
		},
		{
			title = "Verdeckte Operationen",
			hint = "Führt die Pläne des Gnoms gegen die Venture Co. aus.",
			text = [=[Um die Explosionen sei es nie gegangen, beharrte Gaxim. Sie waren eine Ablenkung. Während die Goblins in Panik umherliefen, wurde die wahre Beute genommen: die technischen Pläne aus dem Sägewerk südlich des Felskesselsees und die privaten Briefe der Gesellschaft. Mit ihnen hoffte Gaxim, die Schwächen der Maschinen der Goblins zu finden, und vielleicht auch ein paar ihrer Entwürfe zu borgen.]=],
		},
	},
	mentions = {
		{ text = "Die Rast eines Gnoms" },
		{ text = "Ein alter Kollege" },
		{ text = "Unfähigkeit + Chemikalien = Spaß" },
		{ text = "Eine Schriftrolle von Mauren" },
		{ text = "Sonderlieferung für Gaxim" },
		{ text = "Verdeckte Operation - Alpha" },
		{ text = "Verdeckte Operation - Beta" },
		{ text = "Kaelas Bericht" },
		{
			text = [=[Empfang bei {link:tyrande-whisperwind}Tyrande{/link}, nach den Überfällen]=],
		},
		{ text = "Castpipes Aufgabe" },
	},
	bonds = {
		{ id = "kaela-shadowspear", name = "Kaela Shadowspear", note = "seine Partnerin im Steinkrallengebirge" },
		{ id = "gerenzo-wrenchwhistle", name = "Gerenzo Wrenchwhistle", note = "ein Gnom auf der anderen Seite" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "ehrt jene, die seiner Mission helfen" },
	},
})

Translate("deDE", "seereth-stonebreak", {
	title = "Seereth Stonebreak",
	subtitle = "Schamanin der Horde",
	found = [=[Ehrenmal, an der Grenze zwischen dem Brachland und dem Steinkrallengebirge]=],
	hint = [=[Sucht die Schamanin, die ihr Lager an der westlichen Straße hat, wo das Brachland zum Steinkrallengebirge ansteigt.]=],
	allegiance = "Horde · Orgrimmar",
	aliases = { "Seereth" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Seereth Stonebreak ist eine junge Schamanin der {link:horde}Horde{/link}, die von {link:orgrimmar}Orgrimmar{/link} ausgesandt wurde, um auf die Schreie des Steinkrallengebirges zu antworten. Der alte Scharfseher {link:zor-lonetree}Zor Lonetree{/link} hörte, dass das Land Schmerzen litt. Seereth war es, die er aussandte, um den Grund zu erfahren. Sie fand die Goblins der {link:venture-company}Venture Co.{/link}, die die Wälder fällten und niederbrannten, und seither hat sie ihr Lager an der Grenze aufgeschlagen und sammelt jede Hilfe, die sie bekommen kann.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Seereth ist die erste Antwort der {link:horde}Horde{/link} auf die Not des Steinkrallengebirges. Ihr Wort trug die Angelegenheit zu den Ältesten der {link:tauren}Tauren{/link} und durch sie zu {link:magatha-grimtotem}Magatha Grimtotem{/link} und den {link:forsaken}Verlassenen{/link}. Was als Vision einer Schamanin begann, wurde zu einem Giftkomplott.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie meldet die große Abholzung des Steinkrallengebirges nach {link:orgrimmar}Orgrimmar{/link} und bittet um Hilfe.
• Sie sendet Krieger in die Scherwindklippe gegen die Goblins und ihre Diener.
• Sie träumt von den zwei Schreddern, die die Bäume der Klippe fällen.
• Sie sucht den Rat der Ältesten der {link:tauren}Tauren{/link}, und vor allem den Magathas.]=],
		},
	},
	chapters = {
		{
			title = "Die Stimme des Landes",
			hint = [=[Folgt dem Ruf des Scharfsehers an die Grenze des Steinkrallengebirges.]=],
			text = [=[Seereth hört die Geister des Steinkrallengebirges, wie eine Schamanin sie hört, und was sie hört, ist Zorn. Die Goblins haben die Bäume genommen, und die Geister sind vor Schmerz beinahe blind. Sie rät nicht zur Geduld. Sie bittet darum, der {link:venture-company}Venture Co.{/link} die einzige Sprache zu zeigen, die sie versteht.]=],
		},
		{
			title = "XT:4 und XT:9",
			hint = "Bringt die Maschinen aus Seereths Vision zum Schweigen.",
			text = [=[Das meiste Flüstern der Geister entgeht ihr, doch eine Vision wurde klar: zwei menschengestaltige Maschinen in der Scherwindklippe, die mit unmöglicher Geschwindigkeit Bäume fällten, gekennzeichnet mit den Zeichen XT:4 und XT:9. Als beide zerstört waren, wurden viele der Geister besänftigt. Seereth jubelte nicht. Wenn die Goblins die Berge nicht verließen, warnte sie, stünde Schlimmeres noch bevor.]=],
		},
	},
	mentions = {
		{ text = "Die Geister des Steinkrallengebirges" },
		{ text = "Goblinische Eindringlinge" },
		{ text = "Schreddermaschinen" },
		{ text = "Die Älteste Vettel" },
	},
	bonds = {
		{ id = "zor-lonetree", name = "Zor Lonetree", note = "sandte sie ins Steinkrallengebirge" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "die Älteste, der sie Nachricht sandte" },
		{ id = "makaba-flathoof", name = "Makaba Flathoof", note = "teilt ihr Lager" },
	},
})

Translate("deDE", "maggran-earthbinder", {
	title = "Maggran Earthbinder",
	subtitle = "Verteidiger von Sonnenfels",
	found = "Sonnenfels",
	hint = [=[Sprecht mit dem Tauren, der die Verteidigung von Sonnenfels befehligt.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Maggran" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Maggran Earthbinder ist ein Krieger der {link:tauren}Tauren{/link}, der die Verteidigung von {link:sun-rock-retreat}Sonnenfels{/link} leitet. Er glaubt, dass sein Volk der Beschützer dieser Lande ist, und er nimmt diese Pflicht ernst. Er trägt eine Narbe von den Fängen der Spinne {link:besseleth}Besseleth{/link}, und er führt schon so lange Krieg gegen die {link:harpies}Harpyien{/link} der Blutfurien, dass er nicht sicher ist, was er ohne sie tun wird.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Maggran ist die Hand der {link:horde}Horde{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}. Wo die Schamanen heilen, kämpft er, und die Kopfgelder, die er aussetzt, sind das Maß jeder Gefahr in den Bergen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er setzt Kopfgelder auf die {link:harpies}Harpyien{/link} der Blutfurien und auf ihre Königin aus.
• Er setzt einen Preis auf den Kopf von {link:besseleth}Besseleth{/link} aus, der Spinne des Sishircanyons, die ihn einst verwundete.
• Er schickt einen Reservekrieger, um Grish Longrunner am großen Aufzug abzulösen, damit der junge {link:the-night-watch}Wächter{/link} seine Familie besuchen kann.
• Er sendet die Sonnensteine der Harpyien an {link:mor-rogal}Mor'rogal{/link}, der Verwendung für sie hat.]=],
		},
	},
	chapters = {
		{
			title = "Die Harpyienplage",
			hint = "Folgt Maggrans Ruf gegen die Harpyien der Blutfurien.",
			text = [=[Maggran sieht die Blutfurien nicht als ein örtliches Übel. Für ihn sind sie der Ursprung der {link:harpies}Harpyien{/link}, die ganz {link:kalimdor}Kalimdor{/link} plagen, eine Krankheit, die sich vom verbrannten Tal aus verbreitet und Unschuldige in ihren Grenzen gefangen hält. Ihre Zahl zu verringern, genügt nicht. Das Heilmittel, sagt er, ist ihre Königin.]=],
		},
		{
			title = "Nach der Ripper",
			hint = "Bringt die Königin der Harpyien der Blutfurien zu Fall.",
			text = [=[Als die {link:bloodfury-ripper}Bloodfury Ripper{/link} erschlagen war, wich der Zorn aus Maggran. Das überraschte ihn. Jahrelang hatte das Böse neben seinem Land seine Gedanken scharf gehalten, und nun waren sie still. Vielleicht, sagte er, sei das gut. Vielleicht könne er sich nun dem Guten zuwenden, wie es sich für einen {link:tauren}Tauren{/link} gehört.]=],
		},
		{
			title = "Die alte Jägerin",
			hint = "Beendet die Bedrohung des Sishircanyons.",
			text = [=[{link:besseleth}Besseleth{/link} ist eine alte Jägerin dieser Hügel. Sie erwischte Maggran einst nachts auf dem {link:webwinder-path}Weberpass{/link}, und er entkam ihr nur knapp. Nun, da sie fort ist, hofft er, dass mehr Reisende nach {link:sun-rock-retreat}Sonnenfels{/link} kommen werden, ohne zu fürchten, was im Dunkeln lauert.]=],
		},
	},
	mentions = {
		{ text = "{link:harpies}Harpyien{/link} drohen" },
		{ text = "Die Blutlinie der Blutfurien" },
		{
			text = [=[Arachnophobie, von einem Warnschild im {link:webwinder-path}Sishircanyon{/link}]=],
		},
		{ text = "Die Reserve rufen" },
		{ text = "Schmuck der Blutfurien" },
	},
	bonds = {
		{ id = "bloodfury-ripper", name = "Bloodfury Ripper", note = "die Königin, die er tot sehen wollte" },
		{ id = "besseleth", name = "Besseleth", note = "hinterließ ihm eine Narbe" },
		{ id = "mor-rogal", name = "Mor'rogal", note = "erhält die Sonnensteine" },
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "dient mit ihm Sonnenfels" },
	},
})

Translate("deDE", "tammra-windfield", {
	title = "Tammra Windfield",
	subtitle = "Heilerin des Landes",
	found = "Sonnenfels",
	hint = [=[Sucht die Taurin von Sonnenfels, die das Land mit den Segnungen der Erdmutter zu heilen versucht.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Tammra" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tammra Windfield ist eine Taurin von {link:sun-rock-retreat}Sonnenfels{/link}, die es sich zur Aufgabe gemacht hat, das {link:stonetalon-mountains}Steinkrallengebirge{/link} zu heilen. Sie glaubt, dass nur die Segnungen der Erdmutter die Wunden heilen können, die Gier und Krieg hinterlassen haben. Sie arbeitet mit Samen, Gesängen und Geduld. Sie ist auch die Tante von {link:kaya-flathoof}Kaya Flathoof{/link}, einem Mädchen, das {link:grimtotem-clan}die Grimmtotem{/link} verschleppten und das ihre Familie für tot hielt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tammra ist das andere Gesicht der {link:horde}Horde{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}. Wo die Krieger von {link:sun-rock-retreat}Sonnenfels{/link} die {link:harpies}Harpyien{/link} dezimieren, pflanzt sie. Ihre Hoffnung ist, dass eines Tages die {link:venture-company}Venture Co.{/link} ihre Sägen einpackt, die Feuergeister sich beruhigen und das Land selbst die Harpyien vertreibt.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sammelt Gaea-Samen am {link:mirkfallon-lake}Mirkfallonsee{/link} und erfüllt sie mit schamanistischer Kraft.
• Sie lässt die verzauberten Samen in die fruchtbaren Hügel des verbrannten Tals pflanzen.
• Sie erfährt von der Rettung ihrer Nichte aus den Händen der Grimmtotem.]=],
		},
	},
	chapters = {
		{
			title = "Der Kreislauf der Wiedergeburt",
			hint = "Bringt Tammra die Samen vom Mirkfallonsee.",
			text = [=[Die Gaea-Samen wachsen nur nahe dem Ufer des Mirkfallonsees. Tammra nimmt sie in ihre Hände und singt über ihnen, und die Samen erwachen. Nur wer rein und aufrichtig ist, sagt sie, kann das Land heilen. Sie verlangt von den Samen nichts weiter, als zu wachsen.]=],
		},
		{
			title = "Neues Leben in der Asche",
			hint = "Pflanzt die verzauberten Samen im Herzen der Zerstörung.",
			text = [=[Die Samen wurden im Zentrum der Verwüstung gepflanzt, im verbrannten Tal, zwischen {link:harpies}Harpyien{/link} und brennenden Geistern. Sie werden der Verderbnis widerstehen und anderem Leben einen Halt geben. Mit der Zeit, glaubt Tammra, werden sie das {link:stonetalon-mountains}Steinkrallengebirge{/link} wieder in einen Wald verwandeln. Das wird nicht bald geschehen. Sie erwartet es auch nicht.]=],
		},
		{
			title = "Kaya lebt",
			hint = [=[Bringt Tammra die Nachricht, von der sie glaubte, sie nie zu hören.]=],
			text = [=[Nachdem {link:grimtotem-clan}die Grimmtotem{/link} das Dorf ihrer Verwandten zerstört hatten, glaubte Tammra, ihre Nichte {link:kaya-flathoof}Kaya{/link} sei verloren. Als die Nachricht kam, dass das Mädchen befreit worden war und lebte, konnte Tammra nur danken.]=],
		},
	},
	mentions = {
		{ text = "Kreislauf der Wiedergeburt" },
		{ text = "Neues Leben" },
		{ text = "{link:kaya-flathoof}Kaya{/link} lebt" },
	},
	bonds = {
		{ id = "kaya-flathoof", name = "Kaya Flathoof", note = "ihre Nichte" },
		{ id = "makaba-flathoof", name = "Makaba Flathoof", note = "Kayas Vater" },
		{ id = "maggran-earthbinder", name = "Maggran Earthbinder", note = "dient mit ihr Sonnenfels" },
	},
})

Translate("deDE", "mor-rogal", {
	title = "Mor'rogal",
	subtitle = "Seher von Sonnenfels",
	found = "Die Hügel oberhalb von Sonnenfels",
	hint = [=[Steigt in die Hügel oberhalb von Sonnenfels und sprecht mit dem Tauren, der die Spannung in der Luft spürt.]=],
	allegiance = "Horde · Thunder Bluff",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mor'rogal ist ein Schamane der {link:tauren}Tauren{/link}, der sich in den Hügeln oberhalb von {link:sun-rock-retreat}Sonnenfels{/link} aufhält. Er spürt es, wenn etwas im Land nicht stimmt. In letzter Zeit hat er es stark gespürt. Die Störung, die er wahrnahm, waren weder die Goblins noch die {link:harpies}Harpyien{/link}, sondern etwas tief unter den Bergen, wo die {link:kobolds}Kobolde{/link} der {link:boulderslide-ravine}Steinschlagklamm{/link} gegraben hatten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mor'rogal deckte eine der schwersten Bedrohungen im {link:stonetalon-mountains}Steinkrallengebirge{/link} auf: einen schlafenden Irdenen, ein Geschöpf der Titanen, in Resonit unter der Klamm begraben. Wäre er mit voller Kraft erwacht, so glaubte er, wäre das ganze Steinkrallengebirge verloren gewesen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sendet Sucher in die Höhle der {link:boulderslide-ravine}Steinschlagklamm{/link}, um zu erfahren, was die {link:kobolds}Kobolde{/link} abbauen.
• Er erkennt die Magie der Irdenen im Resonit aus einer alten Legende wieder.
• Er verzaubert das Resonit, um das Behältnis aufzubrechen, das den Irdenen {link:goggeroc}Goggeroc{/link} festhielt.
• Er findet Verwendung für die goldenen Sonnensteine, die die {link:harpies}Harpyien{/link} horten.]=],
		},
	},
	chapters = {
		{
			title = "Der Kristall in der Tiefe",
			hint = [=[Findet heraus, wonach die Kobolde in der Steinschlagklamm graben.]=],
			text = [=[Die Erzproben kamen aus der Höhle zurück, und Mor'rogal drehte sie in seinen Händen, bis er sich erinnerte. Resonit trägt eine Spur der Magie der Irdenen. Die Legenden sagen, dass die Irdenen von den Titanen geschaffen wurden, um das Land selbst zu formen. Wenn die {link:kobolds}Kobolde{/link} tief genug gegraben hatten, um Resonit zu finden, hatten sie tief genug gegraben, um einen Irdenen zu finden.]=],
		},
		{
			title = "Der Irdene erhebt sich",
			hint = [=[Weckt den Schläfer unter der Klamm, bevor er von selbst erwacht.]=],
			text = [=[Mor'rogal konnte nicht verhindern, dass {link:goggeroc}Goggeroc{/link} erwachte. Er beschloss, ihn als Erster zu wecken, solange er von seinem langen Schlaf noch geschwächt war. Mit einem verzauberten Kristall wurde das Behältnis aufgebrochen, und der Irdene wurde erschlagen, bevor seine Kraft zurückkehrte. Mor'rogal nannte es eine Tat, für die ganz {link:kalimdor}Kalimdor{/link} in der Schuld stehen würde.]=],
		},
	},
	mentions = {
		{ text = "{link:boulderslide-ravine}Steinschlagklamm{/link}" },
		{ text = "Der Irdene erhebt sich" },
		{
			text = [=[Schmuck der Blutfurien, gesandt von {link:maggran-earthbinder}Maggran{/link}]=],
		},
	},
	bonds = {
		{ id = "goggeroc", name = "Goggeroc", note = "der Schläfer, den er fürchtete" },
		{ id = "maggran-earthbinder", name = "Maggran Earthbinder", note = "sendet ihm Sonnensteine" },
	},
})

Translate("deDE", "braelyn-firehand", {
	title = "Braelyn Firehand",
	subtitle = "Dienerin eines verborgenen Meisters",
	found = "Sonnenfels",
	hint = [=[Sucht die Fremde in Sonnenfels, die die Druiden des Gipfels hasst.]=],
	allegiance = "Unbekannt · Ein Meister in Jaedenar",
	aliases = { "Braelyn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Braelyn Firehand lebt unter der {link:horde}Horde{/link} in {link:sun-rock-retreat}Sonnenfels{/link}, doch sie ist keine Freundin des Glaubens der {link:tauren}Tauren{/link}. Sie hasst die Druiden des Steinkrallengipfels, die nach ihren Worten den Fluss der Magie über die Berge ersticken. Sie wurde von einem Meister hierhergesandt, der in {link:jaedenar}Jaedenar{/link}, weit im Norden, wartet, und sie darf nicht zurückkehren, bis ihre Arbeit getan ist. Sie spricht vom Zeitalter Azsharas, als erinnere sie sich daran.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Braelyn ist ein Faden von etwas Altem und Dunklem im {link:stonetalon-mountains}Steinkrallengebirge{/link}. Sie nennt den zerstörten Tempel auf dem Gipfel „unseren“ Tempel Azsharas. Sie kannte {link:keeper-ordanus}Ordanus{/link}, einen Sohn des {link:cenarius}Cenarius{/link}, vor langer Zeit, und sie sagt, er habe sich sogar über die Hochgeborenen erhoben. Was auch immer sie ist, sie hungert nach Magie, wie andere nach Brot hungern.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie trachtet den Druiden des {link:cenarius}Cenarius{/link} und den Kindern des Cenarius auf dem Gipfel nach dem Leben.
• Sie jagt {link:keeper-ordanus}Ordanus{/link}, den die Druiden heimlich ins {link:ashenvale}Eschental{/link} fortbrachten.
• Sie entreißt einem gefangenen Druiden die Geheimnisse des Krallenbaus.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Der Name ihres Meisters ist nicht niedergeschrieben. Ebenso wenig steht geschrieben, warum die {link:horde}Horde{/link} sie in {link:sun-rock-retreat}Sonnenfels{/link} wohnen lässt.]=],
		},
	},
	chapters = {
		{
			title = "Ein Brunnen voller Löcher",
			hint = [=[Helft der Zauberin, den Griff der Druiden um die Berge zu lockern.]=],
			text = [=[Im {link:stonetalon-mountains}Steinkrallengebirge{/link}, sagt Braelyn, ist Magie zu schöpfen wie Wasser mit einem Eimer voller Löcher zu schöpfen. Als die Druiden und die Kinder des {link:cenarius}Cenarius{/link} fielen, spürte sie den Fluss zurückkehren, süß und rauschend. Die Kaldorei, sagt sie, sind Narren, ihn zu verschmähen.]=],
		},
		{
			title = "Das Haupt des Ordanus",
			hint = [=[Findet den Sohn des Cenarius, den die Druiden vor ihr versteckten.]=],
			text = [=[Mit ihrer Sicht fand Braelyn ihn: {link:keeper-ordanus}Ordanus{/link}, einen der ältesten Söhne des Waldgottes, versteckt in der Spitze eines großen Baumes in {link:raynewood-retreat}Raynewood{/link} im {link:ashenvale}Eschental{/link}. Die Druiden hatten ihn vom Gipfel fortgebracht, bevor sie ihn erreichen konnte. Als man ihr sein Haupt brachte, betrachtete sie es ohne Mitleid. Sein Haupt, sagte sie, rage nun nicht mehr so hoch.]=],
		},
		{
			title = "Der Hort des Baus",
			hint = "Folgt dem Geheimnis, das Braelyn einem Druiden entriss.",
			text = [=[Die Druiden des Krallenbaus hatten ein sorgfältiges Rätsel aus Schlüsseln erbaut, um ihre Schätze zu bewachen. Braelyn hatte einem von ihnen das Geheimnis entrissen: ein Schlüssel, in einer Laterne versteckt, drei Verstecke und ein Hort im Herzen des Baus.]=],
		},
	},
	mentions = {
		{ text = "Das Vermächtnis des {link:cenarius}Cenarius{/link}" },
		{ text = "{link:keeper-ordanus}Ordanus{/link}" },
		{ text = "Der Bau" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Bewahrer Albagorm", note = "hütet den Gipfel, den sie verachtet" },
	},
})

Translate("deDE", "witch-doctor-jin-zil", {
	title = "Hexendoktor Jin'Zil",
	subtitle = "Hexendoktor von Malaka'jin",
	found = "Seine Hütte in Malaka'jin",
	hint = [=[Sucht den Hexendoktor von Malaka'jin, der drei Käfige neben seiner Hütte hält.]=],
	allegiance = "Horde · Darkspear",
	aliases = { "Jin'Zil" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jin'Zil ist ein Hexendoktor der {link:trolls}Trolle{/link} in {link:malaka-jin}Malaka'jin{/link}. Er ist fröhlich, grausam und alt in den Wegen seiner Kunst. Neben seiner Hütte stehen drei Käfige, und in jedem Käfig sitzt ein {link:night-elves}Nachtelf{/link}. Er nennt sie seine kleinen Freunde, und er gedenkt, ihnen eine Kostprobe dessen zu brauen, was sie Waldmagie nennen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jin'Zil erinnert daran, dass der Krieg zwischen der {link:horde}Horde{/link} und den Kaldorei nicht nur im {link:ashenvale}Eschental{/link} geführt wird. Er ist auch eine Verbindung zu älteren Tagen. Er erinnert sich an die Zeit, als sein Freund Rokhan mit einem wilden Mok'Nathal loszog, um die ältere Schwester der {link:harpies}Harpyie{/link} Serena Bloodfeather zu erschlagen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält drei gefangene {link:night-elves}Nachtelfen{/link} in Käfigen in {link:malaka-jin}Malaka'jin{/link}.
• Er braut für seine Gefangenen einen Trank aus Harz, Schnurrhaaren, Augen und der Schuppe eines Feendrachen.
• Er erfährt von seinem alten Freund Darsok, dass die Letzte der Bloodfeathers tot ist.]=],
		},
	},
	chapters = {
		{
			title = "Waldmagie",
			hint = "Sammelt die seltsamen Zutaten des Hexendoktors.",
			text = [=[Für sein Gebräu wollte Jin'Zil Harz aus dem {link:stonetalon-mountains}Steinkrallengebirge{/link}, Schnurrhaare der Zwielichtläufer, die Augen der Renner und die Schuppe eines Feendrachen. Viele Augen, beharrte er; man hat nie genug. Was der Trank mit den Elfen in den Käfigen anstellte, sagte er nicht. Er versprach nur, dass sie sich dadurch wie zu Hause fühlen würden.]=],
		},
		{
			title = "Ein Brief aus dem Brachland",
			hint = "Bringt den Brief eines alten Freundes nach Malaka'jin.",
			text = [=[Jin'Zil hatte viele Jahre nichts von Darsok gehört. Der Brief teilte ihm mit, dass Serena Bloodfeather tot war, die Letzte ihrer Linie. Er brachte ihm seine Jugend zurück, als er zusah, wie Rokhan mit einem Jäger der Mok'Nathal aufbrach, um ihre ältere Schwester zu töten.]=],
		},
	},
	mentions = {
		{ text = "Brief an Jin'Zil" },
		{ text = "Jin'Zils Waldmagie" },
	},
	bonds = {
		{ id = "ken-zigla", name = "Ken'zigla", note = "braut in Malaka'jin" },
		{ id = "xen-zilla", name = "Xen'Zilla", note = "aus demselben Dorf" },
	},
})

Translate("deDE", "ziz-fizziks", {
	title = "Ziz Fizziks",
	subtitle = "Ingenieur, der die Seiten wechselte",
	found = "Ein Lager am westlichen Rand der Scherwindklippe",
	hint = [=[Sucht den Gobliningenieur, der am westlichen Rand der Scherwindklippe lagert.]=],
	allegiance = "Tinkers' Union · Steamwheedle-Kartell",
	aliases = { "Ziz" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ziz Fizziks war einst der Chefingenieur der Werke der {link:venture-company}Venture Co.{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}. Dann stellte die Gesellschaft einen {link:gnomes}Gnom{/link} ein, {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}, und übertrug ihm die Leitung. Ziz wurde entlassen. Er war so gekränkt, dass er Sputtervalve aus {link:ratchet}Ratchet{/link} anflehte, ihm Arbeit bei der Tinkers' Union zu verschaffen, und nun bespitzelt er seine alten Herren von einem Lager am Rand der Klippe aus.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ziz zeigt, dass die Treue eines Goblins genau so tief reicht wie der Lohn eines Goblins. Er hasst, was die Gesellschaft den Bergen angetan hat, oder so sagt er. Noch weit mehr hasst er es, zugunsten eines Gnoms übergangen worden zu sein.]=],
		},
		{
			title = "Taten",
			text = [=[• Er ließ einen Agenten, {link:piznik}Piznik{/link}, in der Mine der Gesellschaft zurück, um Geheimnisse zu sammeln.
• Er stiehlt die Pläne des Super-Reaper 6000, der großen Holzfällmaschine der Gesellschaft.
• Er sendet die Dokumente und Handbücher der Gesellschaft an Sputtervalve in {link:ratchet}Ratchet{/link}.
• Er setzt einen Preis auf den Kopf von {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link} aus.]=],
		},
	},
	chapters = {
		{
			title = "Der Super-Reaper",
			hint = [=[Helft dem Ingenieur, die Pläne der großen Maschine der Gesellschaft zu stehlen.]=],
			text = [=[Die {link:venture-company}Venture Co.{/link} hatte eine gewaltige Maschine zum Holzfällen gebaut, und Sputtervalve wollte ihre Pläne. Ziz konnte sie nicht selbst holen, denn {link:gerenzo-wrenchwhistle}Gerenzo{/link} wollte ihn auf der Stelle tot sehen. Als die Pläne in seine Hände gelangten, konnte er sie kaum lesen. Er fragte sich laut, wie {link:gnomes}Gnome{/link} es je geschafft hatten, das Rad zu erfinden.]=],
		},
		{
			title = "Der mechanische Arm",
			hint = "Bringt den Gnom zu Fall, der Ziz' Platz einnahm.",
			text = [=[Ziz war {link:gerenzo-wrenchwhistle}Gerenzo{/link} einmal begegnet, und er hatte das verrottende Fleisch und die Zahnräder nicht vergessen. Er hätte sich nie selbst bis zum Turm des Gnoms durchkämpfen können. Als man ihm Gerenzos mechanischen Arm vorlegte, schüttelte Ziz den Kopf. Warum einen Arm abschneiden, um ihn zu ersetzen, fragte er, wenn man einfach einen dritten hinzufügen könnte?]=],
		},
	},
	mentions = {
		{ text = "Ziz Fizziks, gesandt von Sputtervalve" },
		{ text = "Super-Reaper 6000" },
		{ text = "Weitere Anweisungen" },
		{ text = "Gerenzos Befehle" },
		{
			text = [=[Weitere Anweisungen, aus {link:ratchet}Ratchet{/link} zurückgebracht]=],
		},
		{ text = "{link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}" },
	},
	bonds = {
		{ id = "piznik", name = "Piznik", note = "sein Agent in der Mine" },
		{ id = "gerenzo-wrenchwhistle", name = "Gerenzo Wrenchwhistle", note = "nahm seinen Platz ein" },
		{ id = "gazlowe", name = "Gazlowe", note = "herrscht über den Hafen, in dem sein neuer Herr arbeitet" },
	},
})

Translate("deDE", "gerenzo-wrenchwhistle", {
	title = "Gerenzo Wrenchwhistle",
	subtitle = "Aufseher der Venture Co. im Steinkrallengebirge",
	found = "Hoch über dem Felskesselsee, nahe dem großen Wasserrad",
	hint = [=[Stellt Euch dem Gnom, der hoch über dem Felskesselsee über die Werke der Goblins wacht.]=],
	allegiance = "Venture Co.",
	aliases = { "Gerenzo" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gerenzo Wrenchwhistle ist ein {link:gnomes}Gnom{/link} im Dienst der {link:venture-company}Venture Co.{/link} und der Herr ihrer Werke im {link:stonetalon-mountains}Steinkrallengebirge{/link}. Die Goblins stellten ihn ein, zum Zorn ihrer eigenen Ingenieure, und er übernahm die Leitung des ganzen Unternehmens. Sein Anblick ist nicht leicht zu ertragen. Sein Fleisch scheint zu verrotten, und er hat Metall und Zahnräder an seinen Körper gefügt und einige seiner Gliedmaßen durch Maschinen ersetzt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gerenzo ist der seltsamste Diener der Gier der Goblins: ein {link:gnomes}Gnom{/link}, der seinen eigenen Körper der Maschine übergeben hat. Von seinem Hochsitz über dem {link:cragpool-lake}Felskesselsee{/link} treibt er die Zerstörung der Scherwindklippe voran, und unter ihm begann die Gesellschaft, nach einem seltsamen goldgrünen Erz zu graben.]=],
		},
		{
			title = "Taten",
			text = [=[• Er übernahm den Befehl über die Anlage der Gesellschaft im {link:stonetalon-mountains}Steinkrallengebirge{/link} und entließ {link:ziz-fizziks}Ziz Fizziks{/link}.
• Er befahl, große Mengen eines goldgrünen Erzes in der Scherwindmine abzubauen.
• Er hat geschworen, Ziz auf der Stelle zu töten.
• Er ersetzte seinen eigenen Arm durch einen mechanischen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik erzählt, woher Gerenzo kam, wie er seine Gliedmaßen verlor oder warum ein {link:gnomes}Gnom{/link} der {link:venture-company}Venture Co.{/link} dienen sollte.]=],
		},
	},
	chapters = {
		{
			title = "Das goldgrüne Erz",
			hint = "Findet heraus, wonach der Gnom gräbt.",
			text = [=[Niemand unter Gerenzo wusste, warum er so viel von dem goldgrünen Erz wollte. {link:piznik}Piznik{/link} schmuggelte eine Probe aus der Mine, und {link:ziz-fizziks}Ziz{/link} schickte ein Stück an die Ingenieure von Undermine und behielt ein wenig für sich. Was das Erz ist und was Gerenzo daraus machen will, steht nicht geschrieben.]=],
		},
	},
	mentions = {
		{ text = "Gerenzos Befehle" },
		{ text = "Gerenzo Wrenchwhistle" },
	},
	bonds = {
		{ id = "ziz-fizziks", name = "Ziz Fizziks", note = "der Ingenieur, den er ersetzte" },
		{ id = "piznik", name = "Piznik", note = "in die Minen geschickt" },
		{ id = "gaxim-rustfizzle", name = "Gaxim Rustfizzle", note = "ein Gnom auf der anderen Seite" },
	},
})

Translate("deDE", "piznik", {
	title = "Piznik",
	subtitle = "Bergmann und Spion",
	found = "In der Scherwindmine",
	hint = [=[Sucht den Goblin in der Scherwindmine, der nicht so treu ist, wie er scheint.]=],
	allegiance = "Venture Co. · Agent von Ziz Fizziks",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Piznik war einst der zweitwichtigste Goblin in der Anlage der {link:venture-company}Venture Co.{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}. Dann übernahm {link:gerenzo-wrenchwhistle}Gerenzo{/link} den Befehl, entließ Pizniks Chef {link:ziz-fizziks}Ziz Fizziks{/link} und schickte Piznik hinunter, um in den Minen zu arbeiten. Ziz trug ihm auf, zu bleiben und zu lauschen. Das tat er, und er erfuhr, dass Gerenzo große Mengen eines seltsamen goldgrünen Erzes wollte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Piznik ist der Riss in der Mauer der Gesellschaft, ein Goblin im Inneren, der für seinen alten Herrn Ausschau hält.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schmuggelt eine Probe des goldgrünen Erzes aus der Scherwindmine.
• Er plant, sich davonzustehlen und zu {link:ziz-fizziks}Ziz{/link} zu stoßen, sobald der Diebstahl entdeckt wird.]=],
		},
	},
	mentions = {
		{ text = "Gerenzos Befehle" },
		{ text = "Gerenzos Befehle" },
	},
	bonds = {
		{ id = "ziz-fizziks", name = "Ziz Fizziks", note = "sein alter Chef" },
		{ id = "gerenzo-wrenchwhistle", name = "Gerenzo Wrenchwhistle", note = "schickte ihn in die Minen" },
	},
})

Translate("deDE", "tsunaman", {
	title = "Tsunaman",
	subtitle = "Gesandter des Tribunals der Gezeiten",
	found = "Sonnenfels",
	hint = [=[Sucht den Geist des Wassers, der unter der Horde in Sonnenfels weilt.]=],
	allegiance = "Tribunal der Gezeiten · Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tsunaman ist ein Wasserelementar, der mit einem Kriegsauftrag nach {link:sun-rock-retreat}Sonnenfels{/link} gekommen ist. Das Tribunal der Gezeiten sandte ihn, um die Feuerelementare des verbrannten Tals zu vernichten, denn Neptulon der Gezeitenjäger, Herr der Wasserelementare, will seine feurigen Vettern ausgelöscht sehen. Ihr Krieg, sagt er, tobt seit Zeitaltern auf allen Ebenen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tsunaman zeigt, dass die Verwüstung des Steinkrallengebirges die Aufmerksamkeit von Mächten weit jenseits der Berge erregt hat. Das Feuer, das die Goblins im Tal legten, ist zu einer Front in einem weit älteren Krieg der {link:elements}Elemente{/link} geworden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt Krieg gegen die Feuerelementare des verbrannten Tals.
• Er meldet jeden Sieg dem Tribunal der Gezeiten.
• Er sendet Nachricht an {link:je-neu-sancrea}Je'neu Sancrea{/link} im {link:zoram-gar-outpost}Zoram'gar-Außenposten{/link} im {link:ashenvale}Eschental{/link}.]=],
		},
	},
	mentions = {
		{ text = "Elementarkrieg" },
		{ text = "Ärger in der Tiefe" },
	},
	bonds = {
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "heilt, was das Feuer verbrannte" },
	},
})

Translate("deDE", "braug-dimspirit", {
	title = "Braug Dimspirit",
	subtitle = "Schamane der Prüfung des Wissens",
	found = [=[Nahe der Mündung des Steinkrallenpfads im Steinkrallengebirge]=],
	hint = [=[Sucht den weisen Schamanen, der nahe dem Tunnel ins Eschental lagert.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Braug" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Braug Dimspirit ist ein Schamane von großer Weisheit, der sein Lager nahe dem {link:the-talondeep-path}Steinkrallenpfad{/link} hat. Wer die Prüfung des Wissens sucht, kommt zu ihm, nachdem {link:dorn-plainstalker}Dorn Plainstalker{/link} aus {link:thousand-needles}Tausend Nadeln{/link} den Körper geprüft hat. Braug prüft den Geist. Er glaubt, dass die Goblins, die {link:night-elves}Nachtelfen{/link} und viele andere Völker die Schuld an den Nöten Kalimdors teilen, nicht die {link:orcs}Orcs{/link} und die Verlassenen allein.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Braug bewahrt eine alte Überlieferung der {link:horde}Horde{/link}: dass ein Held die Geschichte der Welt kennen muss, nicht nur, wie man in ihr kämpft.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sendet Sucher aus, um das {i}Vermächtnis der Aspekte{/i} aus den Tiefen von Dor'danil im südlichen {link:ashenvale}Eschental{/link} zu bergen.
• Er stellt eine Frage über das Buch und wartet auf die Antwort, so lange es dauert.
• Er sendet jene, die bestehen, weiter zu Parqual Fintallas in der {link:undercity}Undercity{/link}.]=],
		},
	},
	mentions = {
		{ text = "Prüfung des Wissens" },
		{ text = "Prüfung des Wissens" },
		{ text = "Prüfung des Wissens" },
		{ text = "Prüfung des Wissens" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Bewahrer Albagorm", note = "die Kaldorei könnten seine Prüfung behindern" },
	},
})

Translate("deDE", "makaba-flathoof", {
	title = "Makaba Flathoof",
	subtitle = "Überlebender eines niedergebrannten Dorfes",
	found = [=[Ehrenmal, an der Grenze zwischen dem Brachland und dem Steinkrallengebirge]=],
	hint = [=[Sprecht mit dem trauernden Tauren, der an der westlichen Straße des Brachlands lagert.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Makaba" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Makaba Flathoof ist ein Taure, dessen Dorf von den Grimmtotem überfallen wurde. Fast alle darin wurden getötet. Makaba kämpfte, tötete so viele er konnte und entkam knapp mit dem Leben. Nun wartet er an der Straße unterhalb der Berge, und alles, was er sich wünscht, ist, dass mehr von den Grimmtotem tot wären. Er glaubte, seine Tochter {link:kaya-flathoof}Kaya{/link} sei mit den anderen verloren.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Makabas Trauer ist das Maß dessen, was {link:grimtotem-clan}die Grimmtotem{/link} ihrem eigenen Volk anzutun bereit sind.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bittet um Rache an den Grimmtotem vom {link:grimtotem-post}Posten der Grimmtotem{/link}.
• Er nennt {link:grundig-darkcloud}Grundig Darkcloud{/link} als Anführer des Überfalls.
• Er erfährt, dass seine Tochter {link:kaya-flathoof}Kaya{/link} lebt.]=],
		},
	},
	mentions = {
		{ text = "Rächt mein Dorf" },
		{ text = "Tötet {link:grundig-darkcloud}Grundig Darkcloud{/link}" },
		{ text = "{link:kaya-flathoof}Kaya{/link} lebt" },
	},
	bonds = {
		{ id = "kaya-flathoof", name = "Kaya Flathoof", note = "seine Tochter" },
		{ id = "grundig-darkcloud", name = "Grundig Darkcloud", note = "führte den Überfall an" },
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "Kayas Tante" },
	},
})

Translate("deDE", "kaya-flathoof", {
	title = "Kaya Flathoof",
	subtitle = "Gefangene der Grimmtotem",
	found = "Eine Gefangene am Posten der Grimmtotem",
	hint = [=[Sucht die junge Taurin, die am Posten der Grimmtotem gefangen gehalten wird.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Kaya" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kaya Flathoof ist die Tochter von {link:makaba-flathoof}Makaba Flathoof{/link} und die Nichte von {link:tammra-windfield}Tammra Windfield{/link}. Als {link:grimtotem-clan}die Grimmtotem{/link} ihr Dorf zerstörten, brachten sie sie als Gefangene in ihr Lager, und ihre Familie hielt sie für tot. Sie wurde befreit und bat darum, nach {link:grimtotem-post}Camp Aparaje{/link} geführt zu werden. Von dort, sagte sie, kenne sie den Weg nach Hause.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kayas Rettung ist eine der wenigen guten Nachrichten, die das {link:stonetalon-mountains}Steinkrallengebirge{/link} in diesen Tagen hervorgebracht hat.]=],
		},
	},
	mentions = {
		{ text = "Beschützt Kaya" },
		{ text = "Kaya lebt" },
	},
	bonds = {
		{ id = "makaba-flathoof", name = "Makaba Flathoof", note = "ihr Vater" },
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "ihre Tante" },
		{ id = "grundig-darkcloud", name = "Grundig Darkcloud", note = "hielt sie gefangen" },
	},
})

Translate("deDE", "grundig-darkcloud", {
	title = "Grundig Darkcloud",
	subtitle = "Plünderer der Grimmtotem",
	found = "Posten der Grimmtotem",
	hint = [=[Stellt Euch dem Grimmtotem, der die Schläger am Posten der Grimmtotem anführt.]=],
	allegiance = "Clan der Grimmtotem",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grundig Darkcloud ist ein Krieger des {link:grimtotem-clan}Clans der Grimmtotem{/link} und der Anführer einer Schar von Schlägern am {link:grimtotem-post}Posten der Grimmtotem{/link}. Er war es, der den Angriff auf das Dorf von {link:makaba-flathoof}Makaba Flathoof{/link} anführte, und in seinem Lager wurde Makabas Tochter {link:kaya-flathoof}Kaya{/link} gefangen gehalten. Von allen Grimmtotem in den Bergen gilt er als der Schlimmste.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Grundig ist das fleischgewordene Glaubensbekenntnis der Grimmtotem. Sein Clan träumt davon, die niederen Völker aus {link:kalimdor}Kalimdor{/link} zu vertreiben, doch es waren {link:tauren}Tauren{/link}, die er abschlachtete.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte den Überfall an, der ein Taurendorf zerstörte.
• Er hält eine eigene Schar von Schlägern am {link:grimtotem-post}Posten der Grimmtotem{/link}.]=],
		},
	},
	mentions = {
		{ text = "Tötet Grundig Darkcloud" },
	},
	bonds = {
		{ id = "makaba-flathoof", name = "Makaba Flathoof", note = "dessen Dorf er niederbrannte" },
		{ id = "kaya-flathoof", name = "Kaya Flathoof", note = "seine Gefangene" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "Älteste Vettel seines Clans" },
	},
})

Translate("deDE", "bloodfury-ripper", {
	title = "Bloodfury Ripper",
	subtitle = "Königin der Harpyien der Blutfurien",
	found = "Die westlichen Hügel des verbrannten Tals",
	hint = [=[Stellt Euch der Harpyienkönigin, die von den westlichen Hügeln des verbrannten Tals aus herrscht.]=],
	allegiance = "Harpyien der Blutfurien",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Bloodfury Ripper ist die Anführerin der {link:harpies}Harpyien{/link} der Blutfurien, für sie so gut wie eine Königin. Sie herrscht von den westlichen Hügeln des verbrannten Tals aus, und unter ihr haben sich die Harpyien vom {link:stonetalon-mountains}Steinkrallengebirge{/link} aus über {link:kalimdor}Kalimdor{/link} ausgebreitet. {link:tauren}Tauren{/link} wie Kaldorei wollen sie loswerden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Ripper ist das Herz der Harpyienplage. {link:maggran-earthbinder}Maggran Earthbinder{/link} glaubt, dass nur ihr Tod die Blutfurien wirklich schwächen kann.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie herrscht über die {link:harpies}Harpyien{/link} der Blutfurien im verbrannten Tal.
• Ihre Harpyien verwehren den Druiden des Gipfels jeden Zugang zum Tal.]=],
		},
	},
	mentions = {
		{ text = "Die Blutlinie der Blutfurien" },
	},
	bonds = {
		{ id = "maggran-earthbinder", name = "Maggran Earthbinder", note = "will sie tot sehen" },
		{ id = "keeper-albagorm", name = "Bewahrer Albagorm", note = "würde ihresgleichen vertreiben" },
	},
})

Translate("deDE", "besseleth", {
	title = "Besseleth",
	subtitle = "Spinne des Sishircanyons",
	found = "Sishircanyon, westlich des Weberpasses",
	hint = [=[Stellt Euch der großen Spinne, die den Sishircanyon zu ihrem Unterschlupf gemacht hat.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Besseleth ist eine große Spinne, eine alte Jägerin der Hügel des Steinkrallengebirges. Mit ihren achtbeinigen Kindern hat sie den {link:webwinder-path}Sishircanyon{/link} zu einem mit Netzen verhangenen Unterschlupf gemacht. Nachts jagen sie auf dem Weberpass, und Reisende, die ihn nach Einbruch der Dunkelheit begehen, sind ihre Beute. Eine Warnung am Eingang des Canyons fordert alle Vorbeiziehenden auf, nicht weiterzugehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Besseleth ist der Grund, warum die Straße nach {link:sun-rock-retreat}Sonnenfels{/link} bei Nacht gefürchtet ist. Ihr Fang verwundete einst {link:maggran-earthbinder}Maggran Earthbinder{/link} selbst.]=],
		},
	},
	mentions = {
		{ text = "Arachnophobie" },
	},
	bonds = {
		{ id = "maggran-earthbinder", name = "Maggran Earthbinder", note = "sie hinterließ ihm eine Narbe" },
	},
})

Translate("deDE", "goggeroc", {
	title = "Goggeroc",
	subtitle = "Der schlafende Irdene",
	found = "In einem Behältnis aus Resonit am Grund der Steinschlaghöhle",
	hint = "Findet, was unter der Steinschlagklamm schläft.",
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Goggeroc ist ein Irdener, eines der Steinwesen, die nach den Legenden von den Titanen geschaffen wurden, um das Land zu formen. Er schlief unzählige Zeitalter lang in einem Behältnis aus Resonit, tief unter der {link:boulderslide-ravine}Steinschlagklamm{/link}, bis die {link:kobolds}Kobolde{/link} zu ihm hinabgruben. Der Schamane {link:mor-rogal}Mor'rogal{/link} fürchtete, dass das ganze {link:stonetalon-mountains}Steinkrallengebirge{/link} verloren wäre, wenn er mit voller Kraft erwachte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Goggeroc ist ein Blick in die älteste Vergangenheit der Welt, begraben unter den Füßen der Lebenden. Ob er im Zorn erwachte oder nur in Verwirrung, blieb niemand, um ihn zu fragen.]=],
		},
	},
	mentions = {
		{ text = "Der Irdene erhebt sich" },
	},
	bonds = {
		{ id = "mor-rogal", name = "Mor'rogal", note = "fürchtete sein Erwachen" },
	},
})

Translate("deDE", "ken-zigla", {
	title = "Ken'zigla",
	subtitle = "Brauer von Malaka'jin",
	found = "Malaka'jin",
	hint = [=[Sucht den Troll von Malaka'jin, dessen Heiltränke im ganzen Brachland bekannt sind.]=],
	allegiance = "Horde · Darkspear",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ken'zigla ist ein Troll aus {link:malaka-jin}Malaka'jin{/link}, der Heiltränke braut. Als ein {link:orcs}Orc{/link} namens Dogran verwundet zwischen den {link:quilboar}Stacheleber{/link} nahe {link:camp-taurajo}Camp Taurajo{/link} lag, schickten seine Kameraden nach Malaka'jin um einen Heiltrank. Der erste Bote kehrte nie zurück; Goblins töteten ihn auf der Straße. Ken'zigla hatte den Trank dennoch zubereitet und gab ihn dem Nächsten, der kam, mit einer Warnung: die Hälfte jetzt und die Hälfte nach einer Nacht der Ruhe.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ken'ziglas Kunst reicht weit über {link:malaka-jin}Malaka'jin{/link} hinaus. Die Soldaten des Brachlands vertrauen ihren Tränken ihr Leben an.]=],
		},
	},
	mentions = {
		{ text = "Nachricht von Dogran" },
		{ text = "Ken'ziglas Trank" },
	},
	bonds = {
		{ id = "witch-doctor-jin-zil", name = "Hexendoktor Jin'Zil", note = "aus demselben Dorf" },
	},
})

Translate("deDE", "xen-zilla", {
	title = "Xen'Zilla",
	subtitle = "Jäger von Malaka'jin",
	found = "Malaka'jin",
	hint = [=[Sprecht mit dem Troll von Malaka'jin, der die Spinnen der Nacht fürchtet.]=],
	allegiance = "Horde · Darkspear",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Xen'Zilla ist ein Troll aus {link:malaka-jin}Malaka'jin{/link}. Die Jagd in den Bergen hat das Dorf wohlhabend gemacht, doch sie hat auch unerwünschte Gäste angelockt. Die Spinnen des Steinkrallengebirges kommen nachts herab, um aus den {link:camping}Lagern{/link} der {link:trolls}Trolle{/link} zu stehlen. Xen'Zilla behauptet, hier nichts zu fürchten, und geht doch nach Einbruch der Dunkelheit nicht mehr vor die Tür.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Xen'Zilla spricht für das einfache Volk von {link:malaka-jin}Malaka'jin{/link}, das nur sein Fleisch und seine Felle behalten will.]=],
		},
	},
	mentions = {
		{ text = "Blutsauger" },
	},
	bonds = {
		{ id = "besseleth", name = "Besseleth", note = "Mutter der Spinnen, die Xen'Zilla fürchtet" },
	},
})

Translate("deDE", "darn-talongrip", {
	title = "Darn Talongrip",
	subtitle = "Werber für das Eschental",
	found = "Malaka'jin",
	hint = [=[Sucht den Werber in Malaka'jin, der vom Krieg im Norden spricht.]=],
	allegiance = "Horde · Orgrimmar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Darn Talongrip hält Wache in {link:malaka-jin}Malaka'jin{/link} und sammelt Rekruten für den Krieg im {link:ashenvale}Eschental{/link}. Die {link:horde}Horde{/link} hat kürzlich einen Außenposten am {link:the-zoram-strand}Zoramstrand{/link} errichtet, an der fernen Westküste des Waldes der {link:night-elves}Nachtelfen{/link}, und sie kann stets neue Klingen gebrauchen. Er schickt die Willigen zu Kadrak am Wachturm im nördlichen {link:the-barrens}Brachland{/link}, der den Feldzug anführt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Darn ist ein Zeichen dafür, dass der Krieg um das {link:ashenvale}Eschental{/link} bis an den südlichen Fuß des Steinkrallengebirges reicht.]=],
		},
	},
	mentions = {
		{ text = "Meldet Euch bei Kadrak" },
	},
	bonds = {
		{ id = "witch-doctor-jin-zil", name = "Hexendoktor Jin'Zil", note = "teilt das Dorf" },
	},
})
